use genex::prelude::*;
use genex::render::Environment;

fn draw(world: &World, frame: &mut Frame) {
    frame.clear(Color::rgb(150, 180, 215)).ambient(Color::rgb(170, 190, 220), 0.2) // devices that draw no sky
        .sun(vec3(-0.62, 0.45, -0.64), Color::WHITE, 3.0);                       // white: the sky colours it
    frame.environment(Environment::sky());
    let glow = Color::rgb(255, 170, 80);
    frame.tag("lantern");
    frame.point_light(world.lantern, 4.0, glow, 6.0)                                 // the light
        .sphere_with(world.lantern, 0.12, &Material::emissive(glow, 4.0));         // the glass
    for enemy in &world.enemies {
        frame.tag("enemy").id(enemy.id)                                              // a key that stays with it
            .cube_with(Transform::from_translation(enemy.at), &Material::color(Color::rgb(90, 40, 40)));
        frame.end_id();
    }
    if world.shot_changed {
        frame.camera_cut(); // a respawn or cutscene shot, never every frame
    }
}
